import{_ as i,a0 as s,w as b,s as l,ao as o,I as r,x as n,a1 as e,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"马克·沙特尔沃思专访：Ubuntu——不仅仅是桌面端 | LCTT x X-CMD","titleTemplate":false,"description":"马克·沙特尔沃思专访：Ubuntu——不仅仅是桌面端 | LCTT (201403) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"马克·沙特尔沃思专访：Ubuntu——不仅仅是桌面端 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"马克·沙特尔沃思专访：Ubuntu——不仅仅是桌面端 | LCTT (201403) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201403/Mark Shuttleworth interview--Taking Ubuntu beyond desktops","title":"马克·沙特尔沃思专访：Ubuntu——不仅仅是桌面端","tag":"201403","desc":""},"relativePath":"201403/Mark Shuttleworth interview--Taking Ubuntu beyond desktops.md","filePath":"[post].md"}'),p={name:"201403/Mark Shuttleworth interview--Taking Ubuntu beyond desktops.md"};function d(h,t,U,k,g,T){const u=s("Link");return b(),l("div",null,[t[15]||(t[15]=o('<h1 id="马克·沙特尔沃思专访-ubuntu——不仅仅是桌面端" tabindex="-1">马克·沙特尔沃思专访：Ubuntu——不仅仅是桌面端 <a class="header-anchor" href="#马克·沙特尔沃思专访-ubuntu——不仅仅是桌面端" aria-label="Permalink to “马克·沙特尔沃思专访：Ubuntu——不仅仅是桌面端”">​</a></h1><p>也许，他已经从Canonical公司CEO的位置退了下来，但马克·沙特尔沃思仍然是最能代表Ubuntu的公众人物。</p><p>2013年年初，他在Ubuntu Edge众筹项目上栽了跟头，除了现金，他争取到了许多个人资本的支持，但是距离最终的宏大目标还是相差甚远。然而，他告诉我们该项目并非完全失败，并且甚至有可能被所有知名的智能手机制造商所模仿。</p><h4 id="问-ubuntu将会继续专注于桌面多长时间" tabindex="-1">问：Ubuntu将会继续专注于桌面多长时间？#### <a class="header-anchor" href="#问-ubuntu将会继续专注于桌面多长时间" aria-label="Permalink to “问：Ubuntu将会继续专注于桌面多长时间？####”">​</a></h4><p><strong>答：</strong>如果你有观察到我们在桌面、手机和平板上已完成的设计工作，会发现我们已经针对性地完成了一些工作，这样我们就可以将它们整合为同一个代码库。目前我们正在努力的移动端代码同时也是未来的桌面代码库：你的手机就可以给你一个桌面环境，因为它本身就包含了所有的桌面端代码。</p><blockquote><p>目前我们正在努力的移动端代码同时也是未来的桌面代码库</p></blockquote><p>实际的代码合并会在下一个主周期里的某个时间点进行 - 不会在14.04版本中，但有可能在14.10或15.04中。我们相信我们有能力赶在微软完成合并移动端和PC端的Windows系统前完成这一计划，尽管微软公司表示这是它在设计和发展上的目标。</p><p>一旦我们合并完这些代码，就会产生一个疑问：六个月的发行周期还是否有必要。因为手机和平板用户习惯于在任何时刻更新手机系统，因此我们可能会软化六个月的周期，改为随时发布更新。</p><h4 id="问-安卓和ios已经发展得很好了-你是如何鼓舞开发者们为ubuntu开发应用程序的呢" tabindex="-1">问：安卓和iOS已经发展得很好了，你是如何鼓舞开发者们为Ubuntu开发应用程序的呢？#### <a class="header-anchor" href="#问-安卓和ios已经发展得很好了-你是如何鼓舞开发者们为ubuntu开发应用程序的呢" aria-label="Permalink to “问：安卓和iOS已经发展得很好了，你是如何鼓舞开发者们为Ubuntu开发应用程序的呢？####”">​</a></h4>',9)),r("p",null,[t[1]||(t[1]=r("strong",null,"答：",-1)),t[2]||(t[2]=n(" 这个问题很关键。Ubuntu是各种",-1)),e(u,{href:"http://www.cloudpro.co.uk/"},{default:a(()=>[...t[0]||(t[0]=[n("云计算",-1)])]),_:1}),t[3]||(t[3]=n("上的首要平台 - 例如，Instagram全部部署在Ubuntu上，人们移动设备里运行的游戏和服务后端也运行在Ubuntu云上。因此，在这方面，我们有很强烈的责任感。",-1))]),t[16]||(t[16]=o('<p>我认为在Ubuntu和Windows 8之间最关键的不同是，Ubuntu基于Linux，就像安卓一样。这意味着相比Windows，为安卓平台设计的web应用和原生应用与Ubuntu的关系会更紧密一些。很多安卓开发者使用Ubuntu，在Ubutu上开发应用程序，因此对他们来说同时瞄准这两个平台开发更加容易。</p><h4 id="问-目前有任何硬件合作者有意向生产ubuntu手机和平板吗" tabindex="-1">问：目前有任何硬件合作者有意向生产Ubuntu手机和平板吗？#### <a class="header-anchor" href="#问-目前有任何硬件合作者有意向生产ubuntu手机和平板吗" aria-label="Permalink to “问：目前有任何硬件合作者有意向生产Ubuntu手机和平板吗？####”">​</a></h4><p><strong>答：</strong>我们在很多家居品牌上看到了测试设备。但这些公司都是由内部团队来决定未来如何选择，外界很难去影响他们，真正能促使他们做出决定的只有他们自己感兴趣的东西。</p><p>但是我们也发现了很多公司将Ubuntu平台部署在一些前沿的设备上。既然Ubuntu也是Linux，所以对他们而言如果想要流水线生产安卓设备相对更容易。这是一个十分强烈的兴趣信号，暗示他们正在独立地将Ubuntu安装到设备上并将其呈现给运营商。</p><h4 id="问-你是否对ubuntu-edge没能获得资助感到失望" tabindex="-1">问：你是否对Ubuntu Edge没能获得资助感到失望？#### <a class="header-anchor" href="#问-你是否对ubuntu-edge没能获得资助感到失望" aria-label="Permalink to “问：你是否对Ubuntu Edge没能获得资助感到失望？####”">​</a></h4><p><strong>答：</strong>的确，我感到非常失望，因为我们没有能够将它转变成现实。我持续地收到人们发来的电子邮件，在其中写到“我支持Edge，为它没有诞生感到难过”。但我还是备受打击，毕竟我们没有达到预定目标。对我们来说设备的自主生产才会是一个巨大的保证，但如果你考虑已有的手机生产商，他们可能会以较低的[资金]上限来对待Edge。</p><p>我们也看到了更多人更多地开始对融合更感兴趣。人们都在说，“是的，移动处理器正在追上桌面台式机”。苹果发布下一代iPhone [5s]时，它声称处理器是“桌面级的”，我认为这并非偶然。</p><p>要说苹果过早地幸灾乐祸，可能性不大，因此我们认为这一说法传递了一个非常清晰的信号：iPhone手机和MacBook Air笔记本电脑将会进行整合。除非你打算用这种CPU去制造一台桌面设备，否则去讨论这种CPU的机器性能是没有任何意义的。</p><p>因此，当我为我们没有成功实现Edge感到失望时，我也确信这个想法会被实现的。未来我们将重点关注如何为这个融合的世界提供最好的软件栈。</p><h4 id="问-你个人使用的是什么类型的智能手机" tabindex="-1">问：你个人使用的是什么类型的智能手机？#### <a class="header-anchor" href="#问-你个人使用的是什么类型的智能手机" aria-label="Permalink to “问：你个人使用的是什么类型的智能手机？####”">​</a></h4><p><strong>答：</strong>我的智能手机是一台Nexus，并且我已经用Ubuntu替换掉了安卓。我也拥有一些运行着Windows Phone，iOS和安卓的设备。这样可以帮助我持续了解什么是用户期望得到的东西。</p><h4 id="问-ubuntu电视的开发进度如何-它在2012就已经发布-但从此却杳无音讯了。" tabindex="-1">问：Ubuntu电视的开发进度如何？它在2012就已经发布，但从此却杳无音讯了。#### <a class="header-anchor" href="#问-ubuntu电视的开发进度如何-它在2012就已经发布-但从此却杳无音讯了。" aria-label="Permalink to “问：Ubuntu电视的开发进度如何？它在2012就已经发布，但从此却杳无音讯了。####”">​</a></h4><p><strong>答：</strong> Ubuntu电视已经并入到移动端代码了。目前我们正致力于生产。这次发行可能是手机，下次是平板，最后一切都将融合在一起。我们将拥有一个独有代码库，跨越所有不同形式因素的Ubuntu经验代码库。</p><hr>',14)),r("p",null,[t[5]||(t[5]=n("via: ",-1)),e(u,{href:"http://www.pcpro.co.uk/news/interviews/386080/mark-shuttleworth-interview-taking-ubuntu-beyond-desktops"},{default:a(()=>[...t[4]||(t[4]=[n("http://www.pcpro.co.uk/news/interviews/386080/mark-shuttleworth-interview-taking-ubuntu-beyond-desktops",-1)])]),_:1})]),r("p",null,[t[8]||(t[8]=n("译者：",-1)),e(u,{href:"https://github.com/KayGuoWhu"},{default:a(()=>[...t[6]||(t[6]=[n("KayGuoWhu",-1)])]),_:1}),t[9]||(t[9]=n(" 校对：",-1)),e(u,{href:"http://blog.csdn.net/tinyeyeser"},{default:a(()=>[...t[7]||(t[7]=[n("Mr小眼儿",-1)])]),_:1})]),r("p",null,[t[12]||(t[12]=n("本文由 ",-1)),e(u,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[10]||(t[10]=[n("LCTT",-1)])]),_:1}),t[13]||(t[13]=n(" 原创翻译，",-1)),e(u,{href:"http://linux.cn/"},{default:a(()=>[...t[11]||(t[11]=[n("Linux中国",-1)])]),_:1}),t[14]||(t[14]=n(" 荣誉推出",-1))])])}const C=i(p,[["render",d]]);export{f as __pageData,C as default};
